fromSignalDecisionOutcome :: SignalDecisionOutcome -> Text
fromSignalDecisionOutcome = \case
  SignalDecisionOutcome'APPROVE -> "APPROVE"
  SignalDecisionOutcome'REVIEW -> "REVIEW"
  SignalDecisionOutcome'REJECT -> "REJECT"
